-- Migración 0016. USUARIOS guarda cuentas internas.
-- USUARIOS_ORIGENES indica si USUARIO_ID es interno (ID = 1) o de otro sistema.
-- En LOTES, LOTES_REFERENCIAS, EXPEDICIONES y EXPEDICIONES_LOTES,
-- USUARIO_ID e ID_ORIGEN_USUARIO van juntos: ambos null o ambos con valor.
-- Si el origen es 1, USUARIO_ID debe existir en USUARIOS.
-- No editar este archivo. El siguiente cambio va en una migración nueva
-- y debe reflejarse en db/init.sql.

BEGIN;

CREATE TABLE "USUARIOS_ORIGENES" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CODIGO" text NOT NULL UNIQUE,
  "NOMBRE" text NOT NULL,
  "ACTIVO" boolean NOT NULL DEFAULT true,
  "ES_SEMILLA" boolean NOT NULL DEFAULT false,
  "CREADO_EN" timestamptz NOT NULL DEFAULT now(),
  "ACTUALIZADO_EN" timestamptz NOT NULL DEFAULT now()
);

INSERT INTO "USUARIOS_ORIGENES" ("ID", "CODIGO", "NOMBRE", "ES_SEMILLA") VALUES
  (1, 'interno', 'Interno', true);

SELECT setval(
  pg_get_serial_sequence('"USUARIOS_ORIGENES"', 'ID'),
  (SELECT MAX("ID") FROM "USUARIOS_ORIGENES")
);

CREATE TABLE "USUARIOS" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CODIGO" text NOT NULL UNIQUE,
  "NOMBRE" text NOT NULL,
  "ACTIVO" boolean NOT NULL DEFAULT true,
  "ES_SEMILLA" boolean NOT NULL DEFAULT false,
  "CREADO_EN" timestamptz NOT NULL DEFAULT now(),
  "ACTUALIZADO_EN" timestamptz NOT NULL DEFAULT now()
);

CREATE OR REPLACE FUNCTION usuario_referencia_validar()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF (NEW."USUARIO_ID" IS NULL) <> (NEW."ID_ORIGEN_USUARIO" IS NULL) THEN
    RAISE EXCEPTION 'usuario y origen deben ir juntos' USING ERRCODE = '23514';
  END IF;

  IF NEW."USUARIO_ID" IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW."ID_ORIGEN_USUARIO" = 1
     AND NOT EXISTS (
       SELECT 1 FROM "USUARIOS" WHERE "ID" = NEW."USUARIO_ID"
     ) THEN
    RAISE EXCEPTION 'usuario interno inexistente' USING ERRCODE = '23503';
  END IF;

  RETURN NEW;
END;
$$;

ALTER TABLE "LOTES"
  ADD COLUMN "ID_ORIGEN_USUARIO" integer,
  ADD CONSTRAINT "LOTES_ID_ORIGEN_USUARIO_FK"
    FOREIGN KEY ("ID_ORIGEN_USUARIO") REFERENCES "USUARIOS_ORIGENES" ("ID"),
  ADD CONSTRAINT "LOTES_USUARIO_ORIGEN_CHK" CHECK (
    ("USUARIO_ID" IS NULL) = ("ID_ORIGEN_USUARIO" IS NULL)
  );

ALTER TABLE "LOTES_REFERENCIAS"
  ADD COLUMN "ID_ORIGEN_USUARIO" integer,
  ADD CONSTRAINT "LOTES_REFERENCIAS_ID_ORIGEN_USUARIO_FK"
    FOREIGN KEY ("ID_ORIGEN_USUARIO") REFERENCES "USUARIOS_ORIGENES" ("ID"),
  ADD CONSTRAINT "LOTES_REFERENCIAS_USUARIO_ORIGEN_CHK" CHECK (
    ("USUARIO_ID" IS NULL) = ("ID_ORIGEN_USUARIO" IS NULL)
  );

ALTER TABLE "EXPEDICIONES"
  ADD COLUMN "ID_ORIGEN_USUARIO" integer,
  ADD CONSTRAINT "EXPEDICIONES_ID_ORIGEN_USUARIO_FK"
    FOREIGN KEY ("ID_ORIGEN_USUARIO") REFERENCES "USUARIOS_ORIGENES" ("ID"),
  ADD CONSTRAINT "EXPEDICIONES_USUARIO_ORIGEN_CHK" CHECK (
    ("USUARIO_ID" IS NULL) = ("ID_ORIGEN_USUARIO" IS NULL)
  );

ALTER TABLE "EXPEDICIONES_LOTES"
  ADD COLUMN "ID_ORIGEN_USUARIO" integer,
  ADD CONSTRAINT "EXPEDICIONES_LOTES_ID_ORIGEN_USUARIO_FK"
    FOREIGN KEY ("ID_ORIGEN_USUARIO") REFERENCES "USUARIOS_ORIGENES" ("ID"),
  ADD CONSTRAINT "EXPEDICIONES_LOTES_USUARIO_ORIGEN_CHK" CHECK (
    ("USUARIO_ID" IS NULL) = ("ID_ORIGEN_USUARIO" IS NULL)
  );

-- Antes no había origen ni tabla USUARIOS. Se limpia la referencia.
UPDATE "LOTES" SET "USUARIO_ID" = NULL WHERE "USUARIO_ID" IS NOT NULL;
UPDATE "LOTES_REFERENCIAS" SET "USUARIO_ID" = NULL WHERE "USUARIO_ID" IS NOT NULL;
UPDATE "EXPEDICIONES" SET "USUARIO_ID" = NULL WHERE "USUARIO_ID" IS NOT NULL;
UPDATE "EXPEDICIONES_LOTES" SET "USUARIO_ID" = NULL WHERE "USUARIO_ID" IS NOT NULL;

CREATE INDEX "LOTES_ID_ORIGEN_USUARIO_IDX" ON "LOTES" ("ID_ORIGEN_USUARIO");
CREATE INDEX "LOTES_REFERENCIAS_ID_ORIGEN_USUARIO_IDX"
  ON "LOTES_REFERENCIAS" ("ID_ORIGEN_USUARIO");
CREATE INDEX "EXPEDICIONES_ID_ORIGEN_USUARIO_IDX"
  ON "EXPEDICIONES" ("ID_ORIGEN_USUARIO");
CREATE INDEX "EXPEDICIONES_LOTES_ID_ORIGEN_USUARIO_IDX"
  ON "EXPEDICIONES_LOTES" ("ID_ORIGEN_USUARIO");

CREATE TRIGGER "USUARIOS_ORIGENES_ACTUALIZADO_TRG"
  BEFORE UPDATE ON "USUARIOS_ORIGENES"
  FOR EACH ROW
  EXECUTE FUNCTION marcar_actualizado_en();

CREATE TRIGGER "USUARIOS_ACTUALIZADO_TRG"
  BEFORE UPDATE ON "USUARIOS"
  FOR EACH ROW
  EXECUTE FUNCTION marcar_actualizado_en();

CREATE TRIGGER "LOTES_USUARIO_REF_TRG"
  BEFORE INSERT OR UPDATE ON "LOTES"
  FOR EACH ROW
  EXECUTE FUNCTION usuario_referencia_validar();

CREATE TRIGGER "LOTES_REFERENCIAS_USUARIO_REF_TRG"
  BEFORE INSERT OR UPDATE ON "LOTES_REFERENCIAS"
  FOR EACH ROW
  EXECUTE FUNCTION usuario_referencia_validar();

CREATE TRIGGER "EXPEDICIONES_USUARIO_REF_TRG"
  BEFORE INSERT OR UPDATE ON "EXPEDICIONES"
  FOR EACH ROW
  EXECUTE FUNCTION usuario_referencia_validar();

CREATE TRIGGER "EXPEDICIONES_LOTES_USUARIO_REF_TRG"
  BEFORE INSERT OR UPDATE ON "EXPEDICIONES_LOTES"
  FOR EACH ROW
  EXECUTE FUNCTION usuario_referencia_validar();

ALTER TABLE "USUARIOS_ORIGENES" OWNER TO packing;
ALTER TABLE "USUARIOS" OWNER TO packing;
ALTER FUNCTION usuario_referencia_validar() OWNER TO packing;

COMMIT;
